window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d39a5de69cd75d7"]={"versions": [{"id": "FIG-9d39a5de69cd75d7", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskrete/kontinuierliche Trajektorien koppelnder Regelgrößen über einer synchronen Zeitachse).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Domäne <em>Powertrain</em> (Spezifikation: <code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Release R3.0.7).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der zweipfadigen Drehmomentstruktur (<em>Torque-Based Engine Management</em>) für Ottomotoren. Veranschaulichung der Entkopplung von trägem Füllungspfad (Drosselklappe/Luft) und hochdynamischem Wirkungsgradpfad (Zündwinkel) zur Bereitstellung einer sofort abrufbaren Drehmomentreserve (<em>Torque Reserve</em>) bei gleichzeitig konstantem Ist-Moment (<em>Torque Realised</em>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Software-Komponenten (SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>TorqueCoordinator_SWC</code>: Koordiniert externe Momentenanforderungen (z. B. von Getriebesteuerung, ESP/ASR) und zerlegt diese in langsame (<em>Slow</em>) und schnelle (<em>Fast</em>) Sollwerte.\n</li><li><code>AirPathControl_SWC</code>: Wandelt den <code>Slow Torque request</code> in eine Füllungsgröße (<code>Requested Air Charge</code>) und steuert das Drosselklappen- bzw. Ladedruckstellglied an.\n</li><li><code>IgnitionControl_SWC</code>: Berechnet anhand der tatsächlichen Füllung (<code>Delivered Air Charge</code>) und des <code>Fast Torque request</code> den notwendigen Zündwinkelrückzug (<code>Actual Ignition</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Port-Elemente (Sender-Receiver-Kommunikation via RTE):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> (<code>SenderReceiverInterface</code>): Niederfrequente Drehmomentanforderung an den Luftpfad inkl. Vorhaltemoment (Reserve).\n</li><li><code>Fast Torque request</code> (<code>SenderReceiverInterface</code>): Hochfrequente, zylindersynchrone Drehmomentanforderung, die das unmittelbar an der Kurbelwelle wirksame Moment bestimmt.\n</li><li><code>Torque &quot;Reserve&quot; Requested</code>: Differenzsignal $\\Delta M = M_{\\text{slow}} - M_{\\text{fast}}$.\n</li><li><code>Requested Air Charge</code> vs. <code>Delivered Air Charge</code>: Soll- vs. Ist-Zylinderfrischluftmasse (Modellierung der Saugrohrdynamik mit Tiefpass-/PT1-Verhalten).\n</li><li><code>Base Ignition</code> vs. <code>Actual Ignition</code>: Zündzeitpunkt für optimalen Wirkungsgrad ($\\eta_{\\text{opt}}$) vs. nach spät verstellter Zündwinkel ($\\eta &lt; 1$).\n</li><li><code>Torque Reserve Available</code>: Realisierte Momentenreserve im Zylinder, definiert über das Wirkungsgraddefizit $\\Delta \\eta_{\\text{ign}} = f(\\text{Base Ignition} - \\text{Actual Ignition})$.\n</li><li><code>Torque Realised</code>: Das resultierende indizierte/effektive Drehmoment.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Stationärer Ausgangszustand (t &lt; t_1):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> = <code>Fast Torque request</code>.\n</li><li><code>Requested Air Charge</code> = <code>Delivered Air Charge</code>.\n</li><li><code>Actual Ignition</code> = <code>Base Ignition</code> (optimaler thermodynamischer Wirkungsgrad).\n</li><li><code>Torque Realised</code> entspricht exakt der Anforderung.\n</li></ul>\n</li><li><strong>Aufbau der Drehmomentreserve (t_1 ≤ t &lt; t_2):</strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Anforderung einer Drehmomentreserve (z. B. durch Getriebeschaltvorbereitung, Leerlaufregler oder Katalysatorheizung).\n</li><li><code>Slow Torque request</code> springt stufenförmig nach oben; <code>Fast Torque request</code> verharrt auf Basissollwert.\n</li><li><code>Requested Air Charge</code> springt synchron zum langsamen Momentensollwert.\n</li><li><code>Delivered Air Charge</code> folgt asymmetrisch/asymptotisch verzögert (PT1-Saugrohrfüllverzögerung).\n</li><li><strong>Kompensation im Zündpfad:</strong> Proportional zum Anstieg der Füllung wird <code>Actual Ignition</code> stetig nach <em>spät</em> (Wirkungsgradverschlechterung) verstellt.\n</li><li><strong>Ergebnis:</strong> <code>Torque Realised</code> bleibt vollkommen isobar/flach auf dem Niveau des <code>Fast Torque request</code>.\n</li></ul>\n</li><li><strong>Stationäre Reservephase (t_2 ≤ t &lt; t_3):</strong>\n<ul class=\"fig-list\"><li><code>Delivered Air Charge</code> erreicht stationäres Maximum.\n</li><li>Maximale <code>Torque Reserve Available</code> ist aufgebaut. Ein sprunghafter Anstieg des <code>Fast Torque request</code> könnte nun innerhalb eines einzigen Arbeitstakts durch Vorverlegung der Zündung auf <code>Base Ignition</code> umgesetzt werden.\n</li></ul>\n</li><li><strong>Abbau der Reserve (t_3 ≤ t &lt; t_4):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> fällt sprunghaft auf das Niveau des <code>Fast Torque request</code> zurück.\n</li><li><code>Requested Air Charge</code> bricht sofort ein; <code>Delivered Air Charge</code> klingt verzögert ab (Saugrohrentleerung).\n</li><li><code>Actual Ignition</code> wird simultan von <em>spät</em> zurück auf <code>Base Ignition</code> herangeführt.\n</li><li><code>Torque Realised</code> bleibt während der gesamten Entleerungsphase unverändert konstant.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Task-Scheduling &amp; Abtastraten (RTE/OS-Ebene):</strong>\n<ul class=\"fig-list\"><li><strong>Luftpfad:</strong> Verarbeitung in zeitgesteuerten periodischen Tasks (z. B. 10 ms oder 20 ms Rate).\n</li><li><strong>Zündpfad:</strong> Zwingende Ausführung in zylindersegment- bzw. winkelsynchronen Tasks (Event-getriggert über Kurbelwellengeber / Complex Device Driver <code>CDD</code>), um Zyklus-für-Zyklus-Jitter bei der Momentenkompensation zu verhindern.\n</li></ul>\n</li><li><strong>RTE-Datenkonsistenz:</strong>\n<ul class=\"fig-list\"><li>Zwischen <code>AirPathControl_SWC</code> und <code>IgnitionControl_SWC</code> muss zwingend kohärente Datenhaltung gewährleistet sein (Verwendung von impliziten Lese-/Schreibzugriffen <code>Rte_IRead</code> / <code>Rte_IWrite</code> innerhalb der Segment-Tasks zur Vermeidung von Schwebungs- und Drehmomentenschlägen an der Kurbelwelle).\n</li></ul>\n</li><li><strong>Systemgrenzen &amp; Diagnose (Dem/Det):</strong>\n<ul class=\"fig-list\"><li><strong>Thermische Limitierung:</strong> Dauerhafte Zündwinkelspätverstellung treibt die Abgastemperaturen massiv in die Höhe. Applikations-SWCs müssen integrierende Überwachungsfunktionen (Katalysatorschutzzeitglieder) vorsehen, die bei thermischer Überlast die Reserve zwangsweise abbauen.\n</li><li><strong>Verzögerungszeitkompensation:</strong> Der Zündpfad muss das gemessene bzw. über das Saugrohrmodell geschätzte <code>Delivered Air Charge</code>-Signal prädiktiv kompensieren, da fehlerhafte Phasenlagen zwischen Füllungsanstieg und Zündwinkelrückzug zu transienten Momentenspitzen führen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f6147f4d6a2b830f", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskrete/kontinuierliche Trajektorien koppelnder Regelgrößen über einer synchronen Zeitachse).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Domäne <em>Powertrain</em> (Spezifikation: <code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Release R3.0.7).\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der zweipfadigen Drehmomentstruktur (<em>Torque-Based Engine Management</em>) für Ottomotoren. Veranschaulichung der Entkopplung von trägem Füllungspfad (Drosselklappe/Luft) und hochdynamischem Wirkungsgradpfad (Zündwinkel) zur Bereitstellung einer sofort abrufbaren Drehmomentreserve (<em>Torque Reserve</em>) bei gleichzeitig konstantem Ist-Moment (<em>Torque Realised</em>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Software-Komponenten (SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>TorqueCoordinator_SWC</code>: Koordiniert externe Momentenanforderungen (z. B. von Getriebesteuerung, ESP/ASR) und zerlegt diese in langsame (<em>Slow</em>) und schnelle (<em>Fast</em>) Sollwerte.\n</li><li><code>AirPathControl_SWC</code>: Wandelt den <code>Slow Torque request</code> in eine Füllungsgröße (<code>Requested Air Charge</code>) und steuert das Drosselklappen- bzw. Ladedruckstellglied an.\n</li><li><code>IgnitionControl_SWC</code>: Berechnet anhand der tatsächlichen Füllung (<code>Delivered Air Charge</code>) und des <code>Fast Torque request</code> den notwendigen Zündwinkelrückzug (<code>Actual Ignition</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Port-Elemente (Sender-Receiver-Kommunikation via RTE):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> (<code>SenderReceiverInterface</code>): Niederfrequente Drehmomentanforderung an den Luftpfad inkl. Vorhaltemoment (Reserve).\n</li><li><code>Fast Torque request</code> (<code>SenderReceiverInterface</code>): Hochfrequente, zylindersynchrone Drehmomentanforderung, die das unmittelbar an der Kurbelwelle wirksame Moment bestimmt.\n</li><li><code>Torque &quot;Reserve&quot; Requested</code>: Differenzsignal $\\Delta M = M_{\\text{slow}} - M_{\\text{fast}}$.\n</li><li><code>Requested Air Charge</code> vs. <code>Delivered Air Charge</code>: Soll- vs. Ist-Zylinderfrischluftmasse (Modellierung der Saugrohrdynamik mit Tiefpass-/PT1-Verhalten).\n</li><li><code>Base Ignition</code> vs. <code>Actual Ignition</code>: Zündzeitpunkt für optimalen Wirkungsgrad ($\\eta_{\\text{opt}}$) vs. nach spät verstellter Zündwinkel ($\\eta &lt; 1$).\n</li><li><code>Torque Reserve Available</code>: Realisierte Momentenreserve im Zylinder, definiert über das Wirkungsgraddefizit $\\Delta \\eta_{\\text{ign}} = f(\\text{Base Ignition} - \\text{Actual Ignition})$.\n</li><li><code>Torque Realised</code>: Das resultierende indizierte/effektive Drehmoment.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Stationärer Ausgangszustand (t &lt; t_1):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> = <code>Fast Torque request</code>.\n</li><li><code>Requested Air Charge</code> = <code>Delivered Air Charge</code>.\n</li><li><code>Actual Ignition</code> = <code>Base Ignition</code> (optimaler thermodynamischer Wirkungsgrad).\n</li><li><code>Torque Realised</code> entspricht exakt der Anforderung.\n</li></ul>\n</li><li><strong>Aufbau der Drehmomentreserve (t_1 ≤ t &lt; t_2):</strong>\n<ul class=\"fig-list\"><li><em>Trigger:</em> Anforderung einer Drehmomentreserve (z. B. durch Getriebeschaltvorbereitung, Leerlaufregler oder Katalysatorheizung).\n</li><li><code>Slow Torque request</code> springt stufenförmig nach oben; <code>Fast Torque request</code> verharrt auf Basissollwert.\n</li><li><code>Requested Air Charge</code> springt synchron zum langsamen Momentensollwert.\n</li><li><code>Delivered Air Charge</code> folgt asymmetrisch/asymptotisch verzögert (PT1-Saugrohrfüllverzögerung).\n</li><li><strong>Kompensation im Zündpfad:</strong> Proportional zum Anstieg der Füllung wird <code>Actual Ignition</code> stetig nach <em>spät</em> (Wirkungsgradverschlechterung) verstellt.\n</li><li><strong>Ergebnis:</strong> <code>Torque Realised</code> bleibt vollkommen isobar/flach auf dem Niveau des <code>Fast Torque request</code>.\n</li></ul>\n</li><li><strong>Stationäre Reservephase (t_2 ≤ t &lt; t_3):</strong>\n<ul class=\"fig-list\"><li><code>Delivered Air Charge</code> erreicht stationäres Maximum.\n</li><li>Maximale <code>Torque Reserve Available</code> ist aufgebaut. Ein sprunghafter Anstieg des <code>Fast Torque request</code> könnte nun innerhalb eines einzigen Arbeitstakts durch Vorverlegung der Zündung auf <code>Base Ignition</code> umgesetzt werden.\n</li></ul>\n</li><li><strong>Abbau der Reserve (t_3 ≤ t &lt; t_4):</strong>\n<ul class=\"fig-list\"><li><code>Slow Torque request</code> fällt sprunghaft auf das Niveau des <code>Fast Torque request</code> zurück.\n</li><li><code>Requested Air Charge</code> bricht sofort ein; <code>Delivered Air Charge</code> klingt verzögert ab (Saugrohrentleerung).\n</li><li><code>Actual Ignition</code> wird simultan von <em>spät</em> zurück auf <code>Base Ignition</code> herangeführt.\n</li><li><code>Torque Realised</code> bleibt während der gesamten Entleerungsphase unverändert konstant.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Task-Scheduling &amp; Abtastraten (RTE/OS-Ebene):</strong>\n<ul class=\"fig-list\"><li><strong>Luftpfad:</strong> Verarbeitung in zeitgesteuerten periodischen Tasks (z. B. 10 ms oder 20 ms Rate).\n</li><li><strong>Zündpfad:</strong> Zwingende Ausführung in zylindersegment- bzw. winkelsynchronen Tasks (Event-getriggert über Kurbelwellengeber / Complex Device Driver <code>CDD</code>), um Zyklus-für-Zyklus-Jitter bei der Momentenkompensation zu verhindern.\n</li></ul>\n</li><li><strong>RTE-Datenkonsistenz:</strong>\n<ul class=\"fig-list\"><li>Zwischen <code>AirPathControl_SWC</code> und <code>IgnitionControl_SWC</code> muss zwingend kohärente Datenhaltung gewährleistet sein (Verwendung von impliziten Lese-/Schreibzugriffen <code>Rte_IRead</code> / <code>Rte_IWrite</code> innerhalb der Segment-Tasks zur Vermeidung von Schwebungs- und Drehmomentenschlägen an der Kurbelwelle).\n</li></ul>\n</li><li><strong>Systemgrenzen &amp; Diagnose (Dem/Det):</strong>\n<ul class=\"fig-list\"><li><strong>Thermische Limitierung:</strong> Dauerhafte Zündwinkelspätverstellung treibt die Abgastemperaturen massiv in die Höhe. Applikations-SWCs müssen integrierende Überwachungsfunktionen (Katalysatorschutzzeitglieder) vorsehen, die bei thermischer Überlast die Reserve zwangsweise abbauen.\n</li><li><strong>Verzögerungszeitkompensation:</strong> Der Zündpfad muss das gemessene bzw. über das Saugrohrmodell geschätzte <code>Delivered Air Charge</code>-Signal prädiktiv kompensieren, da fehlerhafte Phasenlagen zwischen Füllungsanstieg und Zündwinkelrückzug zu transienten Momentenspitzen führen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9d39a5de69cd75d7", "to": "FIG-f6147f4d6a2b830f", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
